import{_ as s,o,c as t,a2 as a}from"./chunks/framework.BN3Eol-0.js";const p=JSON.parse('{"title":"UXD-041 — The library names its data sources and lists every link: a Planetary models block, a Moon and Mars surface data block, the /science and essay links in the manifest, the one length rule on the source blocks","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/UXD-041-library-names-its-data-sources-and-lists-every-link.md","filePath":"uxs/decisions/UXD-041-library-names-its-data-sources-and-lists-every-link.md"}'),n={name:"uxs/decisions/UXD-041-library-names-its-data-sources-and-lists-every-link.md"};function r(c,e,d,i,l,h){return o(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="uxd-041-—-the-library-names-its-data-sources-and-lists-every-link-a-planetary-models-block-a-moon-and-mars-surface-data-block-the-science-and-essay-links-in-the-manifest-the-one-length-rule-on-the-source-blocks" tabindex="-1">UXD-041 — The library names its data sources and lists every link: a Planetary models block, a Moon and Mars surface data block, the /science and essay links in the manifest, the one length rule on the source blocks <a class="header-anchor" href="#uxd-041-—-the-library-names-its-data-sources-and-lists-every-link-a-planetary-models-block-a-moon-and-mars-surface-data-block-the-science-and-essay-links-in-the-manifest-the-one-length-rule-on-the-source-blocks" aria-label="Permalink to &quot;UXD-041 — The library names its data sources and lists every link: a Planetary models block, a Moon and Mars surface data block, the /science and essay links in the manifest, the one length rule on the source blocks&quot;">​</a></h1><ul><li><strong>Status</strong>: accepted (built; unit tests green, browser checks listed under Verification)</li><li><strong>Date</strong>: 2026-11-14</li><li><strong>Decider</strong>: the operator, 2026-11-14 — &quot;I&#39;m okay with all the recommendations. Go for them.&quot; (the recommendations of <code>docs/wip/2026-11-14-slice-F2-brief.md</code> §12: decisions 29a, 30a, 31a, 32a; 25a, the length rule, is <a href="./UXD-038-one-length-rule-for-the-long-text-pages">UXD-038</a>)</li><li><strong>Answers</strong>: LI2, LI3 of the UX feedback plan (LI1 was closed by A2); Q10; slice F2</li><li><strong>Builds on</strong>: <a href="./UXD-012-one-page-shell">UXD-012</a> (the page shell), <a href="./UXD-014-one-chip-and-filter">UXD-014</a> (&quot;Show all&quot; is the one action chip), <a href="./UXD-038-one-length-rule-for-the-long-text-pages">UXD-038</a> (<code>previewList</code>, <code>ShowAll</code>), ADR-051 (outbound-link stewardship), ADR-095 (the JPL planetary positions)</li><li><strong>Changes</strong>: <code>src/routes/library/+page.svelte</code>, <code>+page.server.ts</code>, <code>source-ids.ts</code> (+ test), <code>scripts/build-link-provenance.ts</code>, <code>static/data/link-provenance.json</code> (regenerated), <code>static/data/source-logos.json</code> (30 sources), <code>static/data/data-sources.json</code> (6 entries), <code>static/data/schemas/data-sources.schema.json</code> (<code>planetary-model</code>), <code>static/data/schemas/link-provenance.schema.json</code> (<code>science</code>, <code>essay</code>), <code>i18n-src/*/data-sources.json</code> (6 descriptions in 14 files), <code>messages/*.json</code> (<code>library_planetary_models</code>, <code>library_surface_data</code> added, <code>library_astro_planets</code> removed), <code>src/lib/link-provenance-coverage.test.ts</code> (new), <code>tests/e2e/library.spec.ts</code>. No image, no hero and no dependency changed.</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><strong>LI2.</strong> JPL was one sentence in the Astrophysics aside (<code>library_astro_planets</code>). The repo uses three JPL things, not &quot;models&quot; in any larger sense: the approximate Keplerian elements (ADR-095; <code>planet-positions-jpl.test.ts</code> holds every planet within 0.6° of them), the planetary physical parameters and the planetary satellite parameters (both linked from the science articles). It does not use the DE ephemerides or Horizons (ADR-058, ADR-085).</p><p><strong>LI3.</strong> The Moon traverse sources lived only in the route files&#39; <code>credit</code> strings. <code>/credits</code> listed two Mars sources and <code>/library</code> none.</p><p><strong>The intro was false.</strong> <code>library_intro_body_1</code> says &quot;Every external link Orrery sends you to lives here&quot;. The /science articles and the essays held 469 and 76 link rows the manifest did not have.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><strong>A &quot;Planetary models (NASA JPL)&quot; block (29a).</strong> Three <code>data-sources.json</code> entries (<code>jpl-keplerian-elements</code>, <code>jpl-planetary-parameters</code>, <code>jpl-satellite-parameters</code>; category <code>planetary-model</code>, a new schema value; licence PD-USGov as the existing <code>jpl-iau-constants</code> entry). The block draws each one&#39;s name as the link and its description under it. The Small-Body Database is not added. <code>jpl-iau-constants</code> stays on <code>/credits</code> as the entry for the Lab&#39;s IAU, EGM96 and IUGG constants; the planet-positions sentence moved out of the Astrophysics aside into <code>jpl-keplerian-elements</code>.</li><li><strong>A &quot;Moon and Mars surface data&quot; block (30a).</strong> Five entries: three new (<code>lroc-nac-traverses</code>, LROC-EDU; <code>usgs-apollo17-traverse</code>, Haase et al. 2019; <code>hirise-zhurong-traverse</code>, PD-NASA) and the two Mars entries <code>/credits</code> already had (<code>nasa-mmgis-rover-traverses</code>, <code>pds-mer-traverses</code>). Each is a source a route file&#39;s <code>credit</code> already names. Chandrayaan-3 and Chang&#39;e 3 are not listed: their polylines are Orrery&#39;s own. <code>source-ids.test.ts</code> reads every Moon and Mars traverse file and fails when a credit names a source the block does not list.</li><li><strong>One source of text for <code>/credits</code> and <code>/library</code>.</strong> Both blocks read name and link from <code>data-sources.json</code> in the server load (<code>source-ids.ts</code> holds the ids) and the description from the same locale overlay <code>/credits</code> uses (<code>getDataSources(locale)</code>), so the two pages cannot drift.</li><li><strong>Every link is in the manifest (31a).</strong> <code>build-link-provenance.ts</code> collects the <code>links[{l,u,t}]</code> of <code>static/data/science/&lt;tab&gt;/&lt;id&gt;.json</code> (category <code>science</code>, entity <code>&lt;tab&gt;/&lt;id&gt;</code>, route <code>/science/&lt;tab&gt;/&lt;id&gt;</code>) and the <code>sources[{title,url}]</code> of the published essays (category <code>essay</code>, entity the slug, route <code>/essays/&lt;slug&gt;</code>). 544 entries added (1,873 to 2,417 rows; 1,540 to 1,924 distinct URLs), 30 new publishers in <code>source-logos.json</code> (each host the build could not classify fails closed, as before), 32 new host rules (30 for the new publishers, 2 for ESO and EOX, which had a row but no rule). <code>link-provenance-coverage.test.ts</code> fails when a /science or essay link is not in the manifest (written red first: 469 and 76 missing). An entry&#39;s <code>route</code> is the page that holds the link, which <code>/library</code> links to, so the schema&#39;s route pattern is widened from one segment to nested routes (<code>/science/&lt;tab&gt;/&lt;id&gt;</code>, <code>/essays/&lt;slug&gt;</code>) rather than pointing these entries at <code>/science</code> and <code>/essays</code>. The categories show on <code>/library</code> as &quot;SCIENCE&quot; and &quot;Essays&quot; (existing messages <code>nav_science</code>, <code>essays_label</code>).</li><li><strong>The blocks stay header asides, one style (32a).</strong> Five <code>aside.data-sources</code> at the head (Audio episodes, Launches data, Astrophysics data, Planetary models, Moon and Mars surface data), no new section and no contents entry; the contents list stays the sources.</li><li><strong>The length rule (25a).</strong> Each source block draws its first 10 entity clusters and a &quot;Show all N&quot; chip (<code>ShowAll</code>, <code>colophon_show_all</code>, <code>data-list</code> = the source id); headers and the contents list stay open, so a <code>#src-&lt;id&gt;</code> link lands on the header with 10 clusters. With 544 more links the Wikipedia block holds 869 clusters; the cap is what keeps the page from growing with them.</li></ol><h2 id="not-done-here" tabindex="-1">Not done here <a class="header-anchor" href="#not-done-here" aria-label="Permalink to &quot;Not done here&quot;">​</a></h2><ul><li>The 30 new <code>source-logos.json</code> <code>license_summary</code> lines are English only (there is no overlay row for them in the 13 locales); the 6 data-source descriptions and the 2 headings are translated.</li><li>The new manifest rows carry <code>last_verified</code> = the build date; the link checker (<code>check-learn-links.ts</code>, <code>npm run fetch</code>) has not seen them.</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Unit: see the commit. Browser results (the three projects, screenshots) are recorded in the slice report; this record is not updated with them.</p><p>Not checked: Firefox and WebKit; whether <code>lroc.im-ldi.com/about/terms</code> names the GeoJSON traverse layers specifically (the entry&#39;s rationale says so); the licence of the published Haase et al. traverse data (the entry&#39;s rationale says so).</p>',13)])])}const y=s(n,[["render",r]]);export{p as __pageData,y as default};
